mapper.select:
select u.*, d.name as dept_name, r.name as role_name from user u left join dept d on u.dept_id = d.id left join role r on u.role_id = r.id
and u.name like concat('%', #{name}, '%')
and u.phone like concat('%', #{phone}, '%')
and u.dept_id = #{deptId}
and u.status = #{status}
order by u.update_time desc
